void PID_HSC_Model_UpdateTID0(RT_MODEL_PID_HSC_Model_T * const PID_HSC_Model_M,
  B_PID_HSC_Model_c_T *localB, DW_PID_HSC_Model_f_T *localDW)
{
  if (rtmIsMajorTimeStep(PID_HSC_Model_M)) {
    /* Update for DiscreteIntegrator: '<S20>/Discrete-Time Integrator' */
    localDW->DiscreteTimeIntegrator_DSTATE +=
      PID_HSC_Model_P.DiscreteTimeIntegrator_gainval * localB->xdotref;

    /* Update for DiscreteIntegrator: '<S20>/Discrete-Time Integrator1' */
    localDW->DiscreteTimeIntegrator1_DSTATE +=
      PID_HSC_Model_P.DiscreteTimeIntegrator1_gainval * localB->VehSpdms;

    /* Update for Memory: '<S3>/Memory1' incorporates:
     *  Gain: '<S114>/Gain'
     */
    localDW->Memory1_PreviousInput_l = localB->BPPTrqCancel;

    /* Update for Memory: '<S116>/Memory7' */
    localDW->Memory7_PreviousInput = localB->hsc_bms_leakage_ena;

    /* Update for Delay: '<S21>/Delay One Step1' */
    localDW->DelayOneStep1_DSTATE = localB->Switch;

    /* Update for Delay: '<S21>/Delay One Step' */
    localDW->DelayOneStep_DSTATE = localB->Switch1;

    /* Update for DiscreteIntegrator: '<S21>/Discrete-Time Integrator3' */
    localDW->DiscreteTimeIntegrator3_DSTATE +=
      PID_HSC_Model_P.DiscreteTimeIntegrator3_gainval * localB->Switch11;
    if (localB->KeepTrackValidity > 0.0) {
      localDW->DiscreteTimeIntegrator3_PrevResetState = 1;
    } else if (localB->KeepTrackValidity < 0.0) {
      localDW->DiscreteTimeIntegrator3_PrevResetState = -1;
    } else if (localB->KeepTrackValidity == 0.0) {
      localDW->DiscreteTimeIntegrator3_PrevResetState = 0;
    } else {
      localDW->DiscreteTimeIntegrator3_PrevResetState = 2;
    }

    /* End of Update for DiscreteIntegrator: '<S21>/Discrete-Time Integrator3' */
  }

  /* Update for Atomic SubSystem: '<S12>/ACC Lookup' */
  PID_HSC_Model_ACCLookup_UpdateTID0(PID_HSC_Model_M, localB->DistanceToIntersection,
    localB->dist_is_valid, &localB->ACCLookup, &localDW->ACCLookup,
    &PID_HSC_Model_P.ACCLookup);

  /* End of Update for SubSystem: '<S12>/ACC Lookup' */
  if (rtmIsMajorTimeStep(PID_HSC_Model_M)) {
    /* Update for Memory: '<S2>/Memory' */
    localDW->Memory_PreviousInput = localB->DischargeLimit;

    /* Update for Memory: '<S2>/Memory1' */
    localDW->Memory1_PreviousInput = localB->ChargeLimit_l;

    /* Update for Memory: '<S3>/Memory2' */
    localDW->Memory2_PreviousInput = localB->IC_d;

    /* Update for Delay: '<S180>/Delay One Step' */
    localDW->DelayOneStep_DSTATE_b = localB->Switch2_m;
  }
}

/* Update for referenced model: 'PID_HSC_Model' */
void PID_HSC_Model_UpdateTID1(void)
{
}

/* Update for referenced model: 'PID_HSC_Model' */
void PID_HSC_Model_UpdateTID2(B_PID_HSC_Model_c_T *localB, DW_PID_HSC_Model_f_T *localDW)
{
  /* Update for Atomic SubSystem: '<S12>/ACC Lookup' */
  PID_HSC_Model_ACCLookup_UpdateTID2(&localB->ACCLookup, &localDW->ACCLookup,
    &PID_HSC_Model_P.ACCLookup);

  /* End of Update for SubSystem: '<S12>/ACC Lookup' */
}

/* Derivatives for referenced model: 'PID_HSC_Model' */
void PID_HSC_Model_Deriv(B_PID_HSC_Model_c_T *localB, XDot_PID_HSC_Model_n_T *localXdot)
{
  /* Derivatives for Atomic SubSystem: '<S12>/ACC Lookup' */
  PID_HSC_Model_ACCLookup_Deriv(localB->EgoSpd, &localB->ACCLookup,
    &localXdot->ACCLookup);

  /* End of Derivatives for SubSystem: '<S12>/ACC Lookup' */
}

/* Model initialize function */
void PID_HSC_Model_initialize(const char_T **rt_errorStatus, boolean_T
  *rt_stopRequested, RTWSolverInfo *rt_solverInfo, const rtTimingBridge
  *timingBridge, int_T mdlref_TID0, int_T mdlref_TID1, int_T mdlref_TID2,
  RT_MODEL_PID_HSC_Model_T *const PID_HSC_Model_M, B_PID_HSC_Model_c_T *localB,
  DW_PID_HSC_Model_f_T *localDW, X_PID_HSC_Model_n_T *localX, rtwCAPI_ModelMappingInfo
  *rt_ParentMMI, const char_T *rt_ChildPath, int_T rt_ChildMMIIdx, int_T
  rt_CSTATEIdx)
{
  /* Registration code */

  /* initialize non-finites */
  rt_InitInfAndNaN(sizeof(real_T));

  /* non-finite (run-time) assignments */
  PID_HSC_Model_P.Saturation_UpperSat = rtInf;
  PID_HSC_Model_P.Saturation2_UpperSat = rtInf;
  PID_HSC_Model_P.Saturation1_UpperSat_n = rtInf;
  PID_HSC_Model_P.Saturation_UpperSat_a = rtInf;

  /* initialize real-time model */
  (void) memset((void *)PID_HSC_Model_M, 0,
                sizeof(RT_MODEL_PID_HSC_Model_T));

  /* setup the global timing engine */
  PID_HSC_Model_M->Timing.mdlref_GlobalTID[0] = mdlref_TID0;
  PID_HSC_Model_M->Timing.mdlref_GlobalTID[1] = mdlref_TID1;
  PID_HSC_Model_M->Timing.mdlref_GlobalTID[2] = mdlref_TID2;
  PID_HSC_Model_M->timingBridge = (timingBridge);

  /* initialize error status */
  rtmSetErrorStatusPointer(PID_HSC_Model_M, rt_errorStatus);

  /* initialize stop requested flag */
  rtmSetStopRequestedPtr(PID_HSC_Model_M, rt_stopRequested);

  /* initialize RTWSolverInfo */
  PID_HSC_Model_M->solverInfo = (rt_solverInfo);

  /* Set the Timing fields to the appropriate data in the RTWSolverInfo */
  rtmSetSimTimeStepPointer(PID_HSC_Model_M, rtsiGetSimTimeStepPtr
    (PID_HSC_Model_M->solverInfo));
  PID_HSC_Model_M->Timing.stepSize0 = (rtsiGetStepSize(PID_HSC_Model_M->solverInfo));

  /* block I/O */
  (void) memset(((void *) localB), 0,
                sizeof(B_PID_HSC_Model_c_T));

  /* states (dwork) */
  (void) memset((void *)localDW, 0,
                sizeof(DW_PID_HSC_Model_f_T));

  /* Initialize DataMapInfo substructure containing ModelMap for C API */
  {
    PID_HSC_Model_InitializeDataMapInfo(PID_HSC_Model_M, localB, localDW, localX);
  }

  /* Initialize Parent model MMI */
  if ((rt_ParentMMI != (NULL)) && (rt_ChildPath != (NULL))) {
    rtwCAPI_SetChildMMI(*rt_ParentMMI, rt_ChildMMIIdx,
                        &(PID_HSC_Model_M->DataMapInfo.mmi));
    rtwCAPI_SetPath(PID_HSC_Model_M->DataMapInfo.mmi, rt_ChildPath);
    rtwCAPI_MMISetContStateStartIndex(PID_HSC_Model_M->DataMapInfo.mmi, rt_CSTATEIdx);
  }
}
